function [m] = molar_mass(sp)
%MOLAR_MASS  drag.species(name): a species' molar mass [kg/kmol].
%   sp: Species (passed a choice, as its option's number)
%   returns m: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = 0;
    if (sp == 0)
        m = 15.9994;
    elseif (sp == 1)
        m = 31.9988;
    elseif (sp == 2)
        m = 28.0134;
    elseif (sp == 3)
        m = 4.0026;
    elseif (sp == 4)
        m = 1.0079;
    elseif (sp == 5)
        m = 14.0067;
    else
        m = 39.948;
    end
end
